/// <summary>The document as the 0.2.0 application knew it: one member ("colour") later versions do not know.</summary>
public sealed class V020Doc : ISyncEntity
{
    public string Id { get; set; } = string.Empty;

    public HlcTimestamp UpdatedAt { get; set; }

    public bool Deleted { get; set; }

    public string? Title { get; set; }

    public decimal Amount { get; set; }

    public DateTimeOffset? Due { get; set; }

    public List<string> Tags { get; set; } = [];

    public string? Colour { get; set; }
}

[JsonSourceGenerationOptions(PropertyNamingPolicy = JsonKnownNamingPolicy.CamelCase)]
[JsonSerializable(typeof(V020Doc))]
internal sealed partial class V020Json : JsonSerializerContext;

/// <summary>A transport that can go offline.</summary>
internal sealed class Switchable(ISyncTransport<V020Doc> inner) : ISyncTransport<V020Doc>
{
    public bool Offline { get; set; }

    public Task<PullResult<V020Doc>> PullAsync(PullRequest request, CancellationToken cancellationToken = default) =>
        Offline ? throw new SyncTransportException(SyncErrorCodes.Unavailable, "offline", isTransient: true) : inner.PullAsync(request, cancellationToken);

    public Task<PushResult<V020Doc>> PushAsync(PushRequest<V020Doc> request, CancellationToken cancellationToken = default) =>
        Offline ? throw new SyncTransportException(SyncErrorCodes.Unavailable, "offline", isTransient: true) : inner.PushAsync(request, cancellationToken);

    public IAsyncEnumerable<StreamEvent<V020Doc>> StreamAsync(Checkpoint since, CancellationToken cancellationToken = default) => inner.StreamAsync(since, cancellationToken);
}

